{
  "probability": 0.99,
  "range_low": 0.92,
  "range_high": 0.99,
  "summary": [
    "Early 2026 pace shows 606 deaths by February, suggesting a high likelihood of reaching 1,000+ deaths by May if the pace continues.",
    "Historical Mediterranean tolls (~2,100–2,200/year) and the spring crossing window imply the target is plausible rather than exceptional.",
    "Undercounting and data gaps inject uncertainty, but policy developments and weather risks could both push outcomes in the same direction.",
    "Calibrated to a high-confidence posterior, acknowledging correlated factors and potential reporting lags."
  ],
  "confidence": "high",
  "narrative": "Using the Mediterranean Missing Migrants reference class, the 606 deaths by February 2026 imply a strong chance of surpassing 1,000 fatalities by late April or early May if conditions persist. While undercounting and weather/SAR dynamics introduce uncertainty, the overall pace and historical context support a high-probability outcome.",
  "justification": {
    "anchor": {
      "probability": 0.35,
      "basis": "Reference class: IOM Missing Migrants Project Mediterranean fatalities; anchor probability chosen as a conservative starting point given historical annual tolls around 2,100–2,200 and current pace through February 2026."
    },
    "factor_updates": [
      {
        "factor": "year_to_date_pace_606_by_feb_2026",
        "direction": "up",
        "magnitude": "strong",
        "rationale": "606 deaths by February implies the potential to exceed 1,000 by May if the pace persists into March–April."
      },
      {
        "factor": "seasonal_crossing_window_march_april",
        "direction": "up",
        "magnitude": "moderate",
        "rationale": "March–April historically see higher crossing activity, reinforcing the pace into the spring."
      },
      {
        "factor": "historical_annual_mediterranean_baseline_2k_plus",
        "direction": "up",
        "magnitude": "moderate",
        "rationale": "Historical totals around 2,100–2,200 per year suggest that 1,000 by spring is plausible with a high early-year rate."
      },
      {
        "factor": "data_reporting_and_under_count_risk",
        "direction": "up",
        "magnitude": "moderate",
        "rationale": "Undercounting and reporting lags could mean final totals exceed observed pace, increasing the chance of hitting 1,000."
      },
      {
        "factor": "weather_sar_conditions_uncertainty",
        "direction": "down",
        "magnitude": "weak",
        "rationale": "Improved SAR capacity or severe weather could dampen fatalities, modestly reducing the pace toward 1,000."
      }
    ],
    "synthesis_rationale": "Integrates a convergence of factors pointing toward a higher likelihood of 1,000+ deaths by May, tempered by data gaps and potential SAR/weather effects. The calibration reflects correlated drivers and keeps a high probability ceiling given the current pace."
  }
}

{
  "probability": 0.99,
  "range_low": 0.92,
  "range_high": 0.99,
  "summary": [
    "606 Mediterranean fatalities reported by February 2026 imply a high pace that could reach 1,000+ by May if it persists.",
    "Historical annual tolls (~2,100–2,200) and an anticipated spring crossing window increase the likelihood of surpassing 1,000 before May.",
    "Underreporting and data gaps likely push totals higher than early counts, reinforcing the likelihood of the event.",
    "Policy crackdowns could dampen crossings, introducing uncertainty and potential downside risk to the projection."
  ],
  "confidence": "high",
  "narrative": "Early 2026 data show a very high pace of Mediterranean fatalities (606 by Feb) with a spring window likely to sustain or amplify crossings. While undercounting and weather/SAR variability add uncertainty, the best evidence supports a high probability of reaching 1,000 deaths before May 2026.",
  "justification": {
    "anchor": {
      "probability": 0.90,
      "basis": "reference class anchored to IOM Mediterranean route fatalities; central Mediterranean toll historically ~2,100–2,200 per year; 606 deaths by February 2026 signals a high but not certain pace toward 1,000+ by May."
    },
    "factor_updates": [
      {
        "factor": "Pace of Mediterranean fatalities in early 2026 (year-to-date deaths as of Feb 2026)",
        "direction": "up",
        "magnitude": "strong",
        "rationale": "606 deaths by February supports a cumulative total exceeding 1,000 if the pace holds through March–April."
      },
      {
        "factor": "Seasonal spring surge in crossings (March–April)",
        "direction": "up",
        "magnitude": "moderate",
        "rationale": "Historical patterns show higher crossing activity in spring, which would magnify the ongoing pace."
      },
      {
        "factor": "Historical baseline around 2,100–2,200 per year",
        "direction": "up",
        "magnitude": "moderate",
        "rationale": "Annual baseline makes crossing 1,000 by spring plausible given a high early pace."
      },
      {
        "factor": "Underreporting and data gaps",
        "direction": "up",
        "magnitude": "moderate",
        "rationale": "Incomplete counts and missing at-sea deaths imply totals could be higher than observed."
      },
      {
        "factor": "Policy crackdown on irregular migration reducing crossings",
        "direction": "down",
        "magnitude": "moderate",
        "rationale": "Deterioration of crossings could dampen fatalities; this creates upside/downside risk to 1,000 threshold."
      },
      {
        "factor": "Weather/SAR conditions and storm activity",
        "direction": "up",
        "magnitude": "moderate",
        "rationale": "Harsh early-2026 weather has been linked to higher risk and fatalities; continued storms could push numbers higher."
      }
    ],
    "synthesis_rationale": "Posterior probability is dominated by the strong signal from year-to-date pace; supportive seasonal and baseline factors push probability upward, while reporting gaps and weather variability add uncertainty, and policy deterrence adds downward risk. Calibration sets final probability at 0.99 with range reflecting residual uncertainty and potential data gaps."
  }
}

